/bin/bash -lc "python - <<'PY'
from pathlib import Path
import json,re,hashlib
x=json.loads(Path('work/flow-state-machine.json').read_text()); a=x['artifacts']; md=Path('work/flow-state-machine.md').read_text(); sm=Path('work/state-machine.md').read_text()
for role in ['customer','kitchen-front','manager']:
 d=json.loads(Path(f'work/flow-{role}.json').read_text())
 ids={f['flow_id']:role+'::'+f['flow_id'] for f in d['flows']}
 pattern=re.compile(r'(?<"'![A-Za-z0-9_-])('"'+ '|'.join(map(re.escape,sorted(ids,key=len,reverse=True)))+r')(?"'![A-Za-z0-9_-])'"')
 def ns(v):
  if isinstance(v,str):return pattern.sub(lambda m:ids[m[0]],v)
  if isinstance(v,list):return [ns(z) for z in v]
  if isinstance(v,dict):return {k:ns(z) for k,z in v.items()}
  return v
 for f in d['flows']:assert ns(f)==next(z for z in x['flows'] if z['flow_id']==ids[f['flow_id']]),f['flow_id']
 for c in d['conflicts_found']:assert ns(c) in x['conflicts_found']
 assert ns(d['artifacts'])==a['upstream_artifacts'][role]
 print(role,': all flows, decisions and artifacts retained with namespace')
assert len({f['flow_id'] for f in x['flows']})==36
assert {m['flow_id'] for m in a['transition_mapping']}=={f['flow_id'] for f in x['flows']}
assert {t for m in a['transition_mapping'] for t in m['transition_ids']}=={t['transition_id'] for t in a['transitions']}
def esc(v):return str(v).replace('&','&amp;').replace('|','&#124;').replace('\\n','<br>')
for t in a['transitions']:
 for p in [md,sm]:
  for k in ['current_state','event','actor','guard','next_state','side_effect','support']:assert esc(t[k]) in p,(t['transition_id'],k)
for obj in x['assumptions']+x['conflicts_found']:
 for p in [md,sm]:
  for k in ['id','status','decision'] if 'decision' in obj else ['id','status','statement','impact']:assert esc(obj[k]) in p,(obj['id'],k)
for f in x['flows']:
 for k in ['trigger','title', 'actors','preconditions','steps','postconditions','completion_criteria']:
  for value in f[k] if isinstance(f[k],list) else [f[k]]:assert esc(value) in md,(f['flow_id'],k)
 for e in f['evidence']:assert esc(e['quote']) in md
us20=next(l for l in Path('input/us-by-role.md').read_text().splitlines() if l.startswith('| US-20 |'))
assert us20 in md and us20 in sm
assert all(hashlib.sha256(Path(s['path']).read_bytes()).hexdigest()==s['sha256'] for s in x['sources'])
assert hashlib.sha256(Path(a['run_context']['review_gate']['path']).read_bytes()).hexdigest()==a['run_context']['review_gate']['sha256']
fr=Path('input/fr-nfr-input.md').read_text().splitlines()
for coll in [x['flows'],a['transitions'],a['invariants'],a['event_policies']]:
 for z in coll:
  for e in z['evidence']:
   row=next(l for l in fr if l.startswith('| '+e['fr_id']+' |'))
   assert e['quote'] in row,e['fr_id']
for c in x['conflicts_found']:
 for q in c['evidence']:assert any(q in l for l in fr if l.startswith('| FR-'))
print('PASS: complete transition mapping, Markdown/JSON content parity, verbatim US-20 and FR-row evidence, hashes unchanged')
print('Document checks only; no application, Mock-up, payment or NFR runtime test was performed.')
PY"

